#[must_use]
pub fn routes_for(surface: HttpSurface) -> impl Iterator<Item = &'static HttpRouteSpec> {
    HTTP_ROUTES.iter().filter(move |route| route.surface == surface)
}

#[must_use]
pub fn find_route(surface: HttpSurface, path: &str) -> Option<&'static HttpRouteSpec> {
    routes_for(surface).find(|route| route.path == path)
}
